1	/// Formats a session's side-menu timestamp per the prototype: today shows
2	/// just the time, the last 6 days show the weekday abbreviation + time, and
3	/// anything older shows the day + abbreviated month. Pure, total; no
4	/// `package:flutter` import, no I/O (Principle V).
5	class ChatSessionTimestampFormatter {
6	  const ChatSessionTimestampFormatter._();
7	
8	  static const _weekdayAbbreviations = ['seg', 'ter', 'qua', 'qui', 'sex', 'sáb', 'dom'];
9	  static const _monthAbbreviations = [
10	    'jan', 'fev', 'mar', 'abr', 'mai', 'jun',
11	    'jul', 'ago', 'set', 'out', 'nov', 'dez',
12	  ];
13	
14	  /// [timestamp] is converted to local time before formatting; [now] is
15	  /// taken as a parameter (never read internally) so callers — and tests —
16	  /// control "today" explicitly.
17	  static String format(DateTime timestamp, {required DateTime now}) {
18	    final local = timestamp.toLocal();
19	    final time =
20	        '${local.hour.toString().padLeft(2, '0')}:${local.minute.toString().padLeft(2, '0')}';
21	
22	    final today = DateTime(now.year, now.month, now.day);
23	    final day = DateTime(local.year, local.month, local.day);
24	    final daysAgo = today.difference(day).inDays;
25	
26	    if (daysAgo <= 0) return time;
