21	/// A plain [Drawer] widget (not a route) listing "Novo Chat", the
22	/// "CONVERSAS" side-menu list, "Meus Registros", and "Configurações" —
23	/// never disposes Home/Chat's `State` underneath (research.md R3).
24	class AppDrawer extends StatefulWidget {
25	  const AppDrawer({super.key});
26	
27	  @override
28	  State<AppDrawer> createState() => _AppDrawerState();
29	}
30	
31	class _AppDrawerState extends State<AppDrawer> {
32	  final _scrollController = ScrollController();
33	  late final StreamSubscription<void> _reauthSubscription;
34	  late final Future<String?> _accountEmail;
35	
36	  @override
37	  void initState() {
38	    super.initState();
39	    _accountEmail = getIt<SecureTokenStorage>().readAccountEmail();
40	    _scrollController.addListener(_maybeRequestNextPage);
41	    _reauthSubscription = context.read<ChatSessionsBloc>().reauthRequired.listen((_) {
42	      if (!mounted) return;
43	      context.read<SessionBloc>().add(const AuthExpiredDetected());
44	    });
45	  }
46	
47	  void _maybeRequestNextPage() {
48	    if (!_scrollController.hasClients) return;
49	    final position = _scrollController.position;
50	    if (position.pixels >= position.maxScrollExtent - 200) {
51	      context.read<ChatSessionsBloc>().add(const SessionsNextPageRequested());
52	    }
53	  }
54	
55	  @override
56	  void dispose() {
57	    _scrollController.dispose();
58	    unawaited(_reauthSubscription.cancel());
59	    super.dispose();
60	  }
61	
62	  @override
63	  Widget build(BuildContext context) {
64	    return Drawer(
65	      backgroundColor: DesignTokens.colorSurfaceElevated,
